import datetime

import pandas as pd


def price_at(prices, items):
    # DataFrame.lookup was removed in pandas 2.0; use label-based indexing per pair.
    # Missing product (row) or store (column) raises KeyError.
    return [float(prices.loc[product, store]) for product, store in items]


def iso_weeks(dates):
    # Series.dt.week was removed in pandas 2.0; use isocalendar().
    series = pd.to_datetime(pd.Series(dates, dtype=object))
    return [int(week) for week in series.dt.isocalendar().week]


def start_of_quarter(year, quarter):
    # pd.datetime was removed in pandas 2.0; use the standard library.
    return datetime.datetime(year, 3 * (quarter - 1) + 1, 1)

