    frame = pd.read_csv(io.StringIO(csv_text))
    # Take the single column as a Series; works for one row as well.
    return frame.iloc[:, 0]


def spread(values):
    # Mean absolute deviation around the mean, ignoring missing values.
    values = pd.Series(values).dropna().astype(float)
    if values.empty:
        return float("nan")
    centre = values.mean()
    return round(float((values - centre).abs().mean()), 4)


def summary(csv_text):
    values = load_values(csv_text)
    return {"count": int(values.count()), "mean": round(float(values.mean()), 4), "spread": spread(values)}

