def top_categories(products, n=3):
    # Missing categories are not a category, so drop them before counting.
    counts = products["category"].dropna().value_counts()
    result = counts.rename_axis("category").reset_index(name="count")
    return result.head(n).reset_index(drop=True)


def category_share(products):
    # normalize=True over non-null values, so missing categories don't count
    # toward the denominator either.
    shares = products["category"].dropna().value_counts(normalize=True)
    return {category: float(round(share, 3)) for category, share in shares.items()}

