from urllib.parse import quote

import httpx

BASE_URL = "http://service"


def make_client(app, token=None):
    headers = {"X-Token": token} if token else {}
    transport = httpx.WSGITransport(app=app)
    return httpx.Client(transport=transport, base_url=BASE_URL, headers=headers)


def search_url(client, query, page=1):
    # Build the query string manually: httpx encodes spaces as '+', but we need '%20'.
    qs = f"q={quote(str(query), safe='')}&page={quote(str(page), safe='')}"
    return f"{BASE_URL}/search?{qs}"


def get_json(client, path):
    response = client.get(path)
    response.raise_for_status()
    return response.json()

