import numpy as np


def brighten(pixels, amount):
    # Compute in a wide signed type so that the addition cannot overflow
    # (NumPy 2 keeps uint8 when adding a Python int), then clip and cast back.
    wide = np.asarray(pixels).astype(np.int64) + int(amount)
    return np.clip(wide, 0, 255).astype(np.uint8)


def mean_brightness(pixels):
    total = np.asarray(pixels).astype(np.int64).sum()
    return round(float(total / np.size(pixels)), 2)

