import numpy as np


def brighten(pixels, amount):
    # Do the arithmetic in a wide signed integer type: under NEP 50 (numpy 2),
    # uint8 array + Python int stays uint8 and wraps around instead of clipping.
    wide = np.asarray(pixels).astype(np.int64)
    return np.clip(wide + int(amount), 0, 255).astype(np.uint8)


def mean_brightness(pixels):
    # Sum in int64 so uint8 values don't overflow.
    total = int(np.asarray(pixels).sum(dtype=np.int64))
    return round(float(total / np.size(pixels)), 2)

