        "hits_per_hour": {"09:00": 2, "10:00": 1, "11:00": 2},
        "slow_events": 2,
        "slowest": [["cart", "u2", "450 ms"], ["home", "u3", "2,300 ms"], ["search", "u2", "1,500 ms"]],
