    slowest = ordered.drop_duplicates(subset="page", keep="first")
    return slowest[["page", "user", "ms"]].reset_index(drop=True)


def flag_slow(events, threshold_ms):
    out = events.copy()
    out["slow"] = (out["ms"] > threshold_ms).astype(bool)
    return out

def latency_rows(table):
    return [
        [page, user, f"{int(ms):,} ms"]
        for page, user, ms in zip(table["page"], table["user"], table["ms"])
    ]

