import pandas as pd

COLUMNS = ["ts", "page", "user", "ms"]


def load_events(records):
    events = pd.DataFrame(list(records), columns=COLUMNS)
    events["ts"] = pd.to_datetime(events["ts"])
    events["ms"] = events["ms"].astype(int)
    return normalise(events)


def normalise(events):
    out = events.copy()
    for column in out.columns:
        # pandas 3 defaults text to the "str" dtype, not object.
        if pd.api.types.is_string_dtype(out[column]):
            out[column] = out[column].str.strip().str.lower()
    return out

def hourly_hits(events):
    counts = events.set_index("ts").resample("h").size()
    return {ts.strftime("%H:%M"): int(n) for ts, n in counts.items()}

def slowest_per_page(events):
    # Sort by page then ms descending; keep the first (slowest) row per page.
    ordered = events.sort_values(["page", "ms"], ascending=[True, False], kind="stable")
    top = ordered.drop_duplicates("page", keep="first")
    return top[["page", "user", "ms"]].reset_index(drop=True)


def flag_slow(events, threshold_ms):
    out = events.copy()
    out["slow"] = out["ms"] > threshold_ms
    return out

def latency_rows(table):
    # DataFrame.applymap was removed in pandas 3; use Series.map on the column.
    formatted = table["ms"].map(lambda v: f"{v:,} ms")
    return table.assign(ms=formatted).values.tolist()

