import pandas as pd


def _is_text(series):
    dtype = series.dtype
    if isinstance(dtype, pd.StringDtype):
        return True
    if dtype == object:
        # Object columns hold text only if every non-missing value is a string.
        return pd.api.types.infer_dtype(series, skipna=True) in ("string", "empty")
    return False


def text_columns(frame):
    return [column for column in frame.columns if _is_text(frame[column])]


