def _bbox_size(text, font):
    left, top, right, bottom = font.getbbox(text)
    return right - left, bottom - top, left, top


def text_size(text):
    width, height, _, _ = _bbox_size(text, ImageFont.load_default())
    return width, height


def label(text, padding=4):
    font = ImageFont.load_default()
    width, height, left, top = _bbox_size(text, font)
    image = Image.new("RGB", (width + 2 * padding, height + 2 * padding), "white")
    ImageDraw.Draw(image).text(
        (padding - left, padding - top), text, fill="black", font=font
    )
    return image

