import pandas as pd


def _is_text_column(series):
    # pandas 3 defaults to the dedicated string dtype; pandas 2 used object.
    if pd.api.types.is_string_dtype(series.dtype) and not pd.api.types.is_object_dtype(series.dtype):
        return True
    if series.dtype != object:
        return False
    non_null = series.dropna()
    return len(non_null) > 0 and all(isinstance(value, str) for value in non_null)


