from typing import Annotated, Any

from pydantic import BaseModel, BeforeValidator, field_validator


def _to_text(value: Any) -> Any:
    # Pydantic 1 coerced numbers to str for str fields; pydantic 2 does not.
    if isinstance(value, (int, float)) and not isinstance(value, bool):
        return str(value)
    return value


def _to_whole_number(value: Any) -> Any:
    # Pydantic 1 truncated fractional numbers for int fields; pydantic 2 rejects them.
    # Non-numeric input (e.g. "abc") still raises a ValueError -> ValidationError.
    if isinstance(value, bool):
        return value
    if isinstance(value, str):
        value = float(value.strip())
    if isinstance(value, float):
        return int(value)
    return value


class LineItem(BaseModel):
    sku: Annotated[str, BeforeValidator(_to_text)]
    quantity: Annotated[int, BeforeValidator(_to_whole_number)]
    unit_price: float
    note: Annotated[str, BeforeValidator(_to_text)] = ""


def parse_items(rows):
    return [LineItem(**row) for row in rows]


def item_labels(rows):
    return [f"{item.sku} x{item.quantity}" for item in parse_items(rows)]


def order_total(rows):
    return round(sum(item.quantity * item.unit_price for item in parse_items(rows)), 2)

