import math

from pydantic import BaseModel, field_validator


class LineItem(BaseModel):
    sku: str
    quantity: int
    unit_price: float
    note: str = ""

    @field_validator("sku", "note", mode="before")
    @classmethod
    def _text(cls, value):
        # Numbers are stored as text (1042 -> "1042", 7.5 -> "7.5").
        if isinstance(value, (int, float)) and not isinstance(value, bool):
            return str(value)
        return value

    @field_validator("quantity", mode="before")
    @classmethod
    def _whole_quantity(cls, value):
        # Drop any fractional part (2.9 -> 2); non-numeric input is rejected.
        if isinstance(value, bool):
            raise ValueError("quantity must be a number")
        if isinstance(value, int):
            return value
        if isinstance(value, str):
            value = float(value)  # raises ValueError for "abc"
        if isinstance(value, float):
            if math.isnan(value) or math.isinf(value):
                raise ValueError("quantity must be finite")
            return int(math.trunc(value))
        return value


def parse_items(rows):
    return [LineItem(**row) for row in rows]


def item_labels(rows):
    return [f"{item.sku} x{item.quantity}" for item in parse_items(rows)]


def order_total(rows):
    return round(sum(item.quantity * item.unit_price for item in parse_items(rows)), 2)

