import pytest
from pydantic import ValidationError
from app.bookings import booking_from_dict, booking_from_row
from types import SimpleNamespace

base = {"guest": "x", "room": "A101", "nights": 1, "check_in": "2024-01-01"}

@pytest.mark.parametrize("override", [
    {"room": "a101"}, {"room": "AB12"}, {"room": "A1011"}, {"room": "1234"},
    {"nights": 0}, {"nights": -2}, {"check_in": "not-a-date"},
])
def test_invalid(override):
    with pytest.raises(ValidationError):
        booking_from_dict({**base, **override})

def test_valid_room_stripped():
    assert booking_from_dict({**base, "room": " Z999 "}).room == "Z999"

def test_row_invalid():
    with pytest.raises(ValidationError):
        booking_from_row(SimpleNamespace(guest="a", room="A1", nights=1, check_in="2024-01-01"))

