    assert load_config("port: 8080\ndebug: yes\n") == {"host": "localhost", "port": 8080, "debug": True, "workers": 1}


def test_load_profiles():
    text = "profile: dev\ndebug: true\n---\nprofile: prod\nworkers: 4\n"
