from urllib3.util.retry import Retry

# urllib3 2.x renamed these: DEFAULT_METHOD_WHITELIST -> DEFAULT_ALLOWED_METHODS,
# method_whitelist -> allowed_methods, BACKOFF_MAX -> DEFAULT_BACKOFF_MAX.
SAFE_METHODS = frozenset(
    getattr(Retry, "DEFAULT_ALLOWED_METHODS", None)
    or getattr(Retry, "DEFAULT_METHOD_WHITELIST")
)
_METHODS_KWARG = "allowed_methods"
_BACKOFF_MAX = getattr(Retry, "DEFAULT_BACKOFF_MAX", None)
if _BACKOFF_MAX is None:
    _BACKOFF_MAX = Retry.BACKOFF_MAX


def make_retry(total=3, backoff=0.5, methods=None, statuses=(429, 502, 503, 504)):
    allowed = frozenset(m.upper() for m in methods) if methods else SAFE_METHODS
    return Retry(
        total=total,
        backoff_factor=backoff,
        status_forcelist=statuses,
        **{_METHODS_KWARG: allowed},
    )


def retries_on(retry, method, status):
    return retry.is_retry(method.upper(), status)


def backoff_schedule(retry, attempts):
    delays = []
    for _ in range(attempts):
        retry = retry.increment(method="GET", url="/")
        delays.append(min(retry.get_backoff_time(), _BACKOFF_MAX))
    return delays


def max_backoff():
    return _BACKOFF_MAX

